    body {
      margin: 0;
      min-height: 100vh;
      font-family: "Inter", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: var(--bg);
      color: var(--text);
      display: flex;
      justify-content: center;
      padding: 20px;
    }

    .page {
      width: min(760px, 100%);
      min-height: calc(100vh - 40px);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 28px 0 110px;
    }

    .stack {
      width: 100%;
      text-align: center;
      display: grid;
      gap: 22px;
    }

    .logo-wrap {
      display: inline-flex;
      justify-content: center;
      margin-bottom: 6px;
    }

    .wordmark {
      font-weight: 800;
      letter-spacing: 0.02em;
      font-size: clamp(2rem, 8vw, 3.3rem);
      line-height: 1;
      color: var(--brand);
      display: inline-flex;
      align-items: baseline;
      gap: 0.02em;
      user-select: none;
    }

    .wordmark .e-missing {
      width: 0.68em;
      height: 0.72em;
      border: 2.5px dashed color-mix(in oklab, var(--brand) 78%, white);
      border-radius: 4px;
      transform: translateY(0.02em);
      display: inline-block;
      margin: 0 0.02em;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.5rem, 3.4vw, 2rem);
      font-weight: 650;
      letter-spacing: -0.015em;
    }

    .subcopy {
      margin: 0 auto;
      max-width: 58ch;
      color: var(--text-muted);
      font-size: clamp(1rem, 2.2vw, 1.08rem);
      line-height: 1.6;
    }

    .search-wrap {
      margin: 2px auto 0;
      width: min(620px, 100%);
      position: relative;
    }

    .search-form {
      display: grid;
      grid-template-columns: 1fr auto;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: #fff;
      overflow: hidden;
      transition: border-color 160ms ease, box-shadow 180ms ease;
    }

    .search-form:focus-within {
      border-color: var(--focus);
      box-shadow: 0 0 0 4px color-mix(in oklab, var(--focus) 20%, transparent);
    }

    .search-input {
      border: 0;
      padding: 0 16px;
      min-height: 56px;
      font: inherit;
      font-size: 1rem;
      color: var(--text);
      width: 100%;
    }

    .search-input::placeholder { color: #8b92a0; }
    .search-input:focus { outline: none; }

    .search-btn {
      border: 0;
      border-left: 1px solid var(--border);
      background: #ffffff;
      color: #4e5561;
      width: 60px;
      cursor: pointer;
      transition: background-color 150ms ease, color 150ms ease;
    }

    .search-btn:hover,
    .search-btn:focus-visible {
      background: var(--surface);
      color: #272e39;
      outline: none;
    }

    .error-bar {
      margin: 2px auto 0;
      width: min(620px, 100%);
      background: var(--surface);
      border: 1px solid var(--surface-2);
      border-radius: 12px;
      color: #6a7280;
      font-size: 0.98rem;
      font-weight: 500;
      letter-spacing: 0.01em;
      padding: 14px 16px;
    }

    .divider {
      margin: 2px auto 0;
      width: min(620px, 100%);
      border: 0;
      border-top: 1px solid #e2e6ec;
    }

    .next {
      display: grid;
      gap: 10px;
      justify-items: center;
    }

    .next h2 {
      margin: 0;
      font-size: 1.05rem;
      font-weight: 600;
      color: #2f3540;
    }

    .recovery-link {
      color: var(--link);
      text-decoration-thickness: 1px;
      text-underline-offset: 0.2em;
      font-weight: 500;
      transition: color 140ms ease;
    }

    .recovery-link:hover,
    .recovery-link:focus-visible {
      color: #4f5561;
      outline: none;
    }

    .cookie-banner {
      position: fixed;
      left: 0;
      right: 0;
      bottom: 0;
      z-index: 20;
      background: #ffffff;
      border-top: 1px solid #dde2e8;
      box-shadow: 0 -8px 28px color-mix(in oklab, #121212 8%, transparent);
      padding: 14px 16px;
    }

    .cookie-inner {
      margin: 0 auto;
      width: min(1020px, 100%);
      display: grid;
      gap: 10px;
      align-items: center;
    }

    .cookie-text {
      margin: 0;
      font-size: 0.91rem;
      line-height: 1.5;
      color: #5b6370;
    }

    .cookie-text a {
      color: #646f82;
      text-underline-offset: 0.18em;
    }

    .manage-btn {
      justify-self: start;
      border: 1px solid #cfd5de;
      background: #ffffff;
      color: #2e3440;
      border-radius: 10px;
      min-height: 42px;
      padding: 0 14px;
      font: inherit;
      font-size: 0.92rem;
      font-weight: 600;
      cursor: pointer;
      transition: background-color 140ms ease, border-color 140ms ease;
    }

    .manage-btn:hover,
    .manage-btn:focus-visible {
      background: var(--surface);
      border-color: #b9c1cd;
      outline: none;
    }

    .modal {
      position: fixed;
      inset: 0;
      z-index: 40;
      display: none;
      place-items: center;
      padding: 22px;
      background: color-mix(in oklab, #121212 34%, transparent);
    }

    .modal[aria-hidden="false"] { display: grid; }

    .panel {
      width: min(560px, 100%);
      background: #ffffff;
      border-radius: 16px;
      box-shadow: var(--shadow);
      border: 1px solid #e1e6ee;
      padding: 22px;
      display: grid;
      gap: 14px;
      animation: appear 220ms ease-out;
    }

    @keyframes appear {
      from { opacity: 0; transform: translateY(8px) scale(0.985); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }

    .panel h3 {
      margin: 0;
      font-size: 1.12rem;
    }

    .panel p {
      margin: 0;
      color: #5f6672;
      line-height: 1.55;
      font-size: 0.94rem;
    }

    .pref {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
      padding: 10px 12px;
      border: 1px solid #e3e8ef;
      border-radius: 10px;
      background: #fbfcfd;
      font-size: 0.93rem;
      color: #2f3744;
    }

    .switch {
      width: 44px;
      height: 26px;
      border-radius: 999px;
      position: relative;
      border: 1px solid #c7cfdb;
      background: #d8dee8;
      cursor: pointer;
    }

    .switch::after {
      content: "";
      position: absolute;
      top: 2px;
      left: 2px;
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: white;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
      transition: transform 150ms ease;
    }

    .switch[aria-checked="true"] {
      background: #8ba5d7;
      border-color: #8ba5d7;
    }

    .switch[aria-checked="true"]::after {
      transform: translateX(18px);
    }

    .panel-actions {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
      margin-top: 4px;
    }

    .btn {
      min-height: 40px;
      border-radius: 10px;
      border: 1px solid #cfd5df;
      background: #fff;
      padding: 0 12px;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      color: #2f3642;
    }

    .btn.primary {
      background: #2f5fa2;
      border-color: #2f5fa2;
      color: #fff;
    }

    @media (min-width: 720px) {
      body { padding: 28px; }
      .page { min-height: calc(100vh - 56px); }
      .cookie-inner {
        grid-template-columns: 1fr auto;
        gap: 18px;
      }
      .manage-btn { justify-self: end; }
    }

    @media (max-width: 480px) {
      .search-input { min-height: 54px; }
      .error-bar { font-size: 0.93rem; }
      .panel { padding: 18px; }
    }
  </style>
</head>
<body>
  <div class="page">
    <main class="stack" aria-labelledby="page-title">
      <div class="logo-wrap" aria-label="IdeaForum logo">
        <div class="wordmark" role="img" aria-label="IdeaForum">
          ID<span class="e-missing" aria-hidden="true"></span>AFORUM
        </div>
      </div>

      <section class="copy">
        <h1 id="page-title">Sorry, we can't find that.</h1>
        <p class="subcopy">Perhaps we can help you find the content you're looking for:</p>
      </section>

      <section class="search-wrap" aria-label="Search IdeaForum">
        <form class="search-form" id="searchForm" action="/search" method="get">
          <label class="sr-only" for="searchInput" style="position:absolute;left:-9999px;">Search IdeaForum</label>
          <input id="searchInput" class="search-input" name="q" type="search" placeholder="Search IdeaForum..." required>
          <button class="search-btn" type="submit" aria-label="Search">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M11 19a8 8 0 1 1 0-16 8 8 0 0 1 0 16Zm10 2-4.35-4.35" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </button>
        </form>
      </section>

      <div class="error-bar" role="status" aria-live="polite">HTTP Error 404</div>
      <hr class="divider">

      <section class="next" aria-labelledby="next-heading">
        <h2 id="next-heading">What's next?</h2>
        <a class="recovery-link" href="/">Go to the homepage</a>
        <a class="recovery-link" href="/help-desk">Visit our Help Desk</a>
      </section>
    </main>
  </div>

  <aside class="cookie-banner" id="cookieBanner" aria-label="Cookie consent">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
        <a href="/privacy-policy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button class="manage-btn" id="openPrefs" type="button">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal" id="prefsModal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="prefsTitle">
    <div class="panel">
      <h3 id="prefsTitle">Cookie & Privacy Preferences</h3>
      <p>Choose which optional technologies IdeaForum can use. Essential cookies remain enabled to support core functionality.</p>

      <div class="pref">
        <span>Essential cookies</span>
        <button class="switch" role="switch" aria-checked="true" aria-label="Essential cookies enabled" disabled></button>
      </div>
      <div class="pref">
        <span>Analytics cookies</span>
        <button class="switch toggle" role="switch" aria-checked="false" aria-label="Toggle analytics cookies"></button>
      </div>
      <div class="pref">
        <span>Personalization cookies</span>
        <button class="switch toggle" role="switch" aria-checked="false" aria-label="Toggle personalization cookies"></button>
      </div>

      <div class="panel-actions">
        <button class="btn" id="closePrefs" type="button">Cancel</button>
        <button class="btn primary" id="savePrefs" type="button">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    const searchForm = document.getElementById('searchForm');
    searchForm.addEventListener('submit', function (event) {
      event.preventDefault();
      const input = document.getElementById('searchInput');
      const query = input.value.trim();
      if (!query) return;
      const target = '/search?q=' + encodeURIComponent(query);
      window.location.href = target;
    });

    const modal = document.getElementById('prefsModal');
    const openPrefs = document.getElementById('openPrefs');
    const closePrefs = document.getElementById('closePrefs');
    const savePrefs = document.getElementById('savePrefs');

    function openModal() {
      modal.setAttribute('aria-hidden', 'false');
      closePrefs.focus();
    }

    function hideModal() {
      modal.setAttribute('aria-hidden', 'true');
      openPrefs.focus();
    }

    openPrefs.addEventListener('click', openModal);
    closePrefs.addEventListener('click', hideModal);
    savePrefs.addEventListener('click', function () {
      hideModal();
      document.getElementById('cookieBanner').style.display = 'none';
    });

    modal.addEventListener('click', function (event) {
      if (event.target === modal) hideModal();
    });

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') {
        hideModal();
      }
    });

    document.querySelectorAll('.toggle').forEach(function (toggle) {
      toggle.addEventListener('click', function () {
        const checked = toggle.getAttribute('aria-checked') === 'true';
        toggle.setAttribute('aria-checked', checked ? 'false' : 'true');
      });
    });
  </script>
</body>
</html>
