      .search-input { min-height: 54px; }
      .error-bar { font-size: 0.93rem; }
      .panel { padding: 18px; }
    }
  </style>
</head>
<body>
  <div class="page">
    <main class="stack" aria-labelledby="page-title">
      <div class="logo-wrap" aria-label="IdeaForum logo">
        <div class="wordmark" role="img" aria-label="IdeaForum">
          ID<span class="e-missing" aria-hidden="true"></span>AFORUM
        </div>
      </div>

      <section class="copy">
        <h1 id="page-title">Sorry, we can't find that.</h1>
        <p class="subcopy">Perhaps we can help you find the content you're looking for:</p>
      </section>

      <section class="search-wrap" aria-label="Search IdeaForum">
        <form class="search-form" id="searchForm" action="/search" method="get">
          <label class="sr-only" for="searchInput" style="position:absolute;left:-9999px;">Search IdeaForum</label>
          <input id="searchInput" class="search-input" name="q" type="search" placeholder="Search IdeaForum..." required>
          <button class="search-btn" type="submit" aria-label="Search">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M11 19a8 8 0 1 1 0-16 8 8 0 0 1 0 16Zm10 2-4.35-4.35" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </button>
        </form>
      </section>

      <div class="error-bar" role="status" aria-live="polite">HTTP Error 404</div>
      <hr class="divider">

      <section class="next" aria-labelledby="next-heading">
        <h2 id="next-heading">What's next?</h2>
        <a class="recovery-link" href="/">Go to the homepage</a>
        <a class="recovery-link" href="/help-desk">Visit our Help Desk</a>
      </section>
    </main>
  </div>

  <aside class="cookie-banner" id="cookieBanner" aria-label="Cookie consent">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
        <a href="/privacy-policy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button class="manage-btn" id="openPrefs" type="button">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal" id="prefsModal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="prefsTitle">
    <div class="panel">
      <h3 id="prefsTitle">Cookie & Privacy Preferences</h3>
      <p>Choose which optional technologies IdeaForum can use. Essential cookies remain enabled to support core functionality.</p>

      <div class="pref">
        <span>Essential cookies</span>
        <button class="switch" role="switch" aria-checked="true" aria-label="Essential cookies enabled" disabled></button>
      </div>
      <div class="pref">
        <span>Analytics cookies</span>
        <button class="switch toggle" role="switch" aria-checked="false" aria-label="Toggle analytics cookies"></button>
      </div>
      <div class="pref">
        <span>Personalization cookies</span>
        <button class="switch toggle" role="switch" aria-checked="false" aria-label="Toggle personalization cookies"></button>
      </div>

      <div class="panel-actions">
        <button class="btn" id="closePrefs" type="button">Cancel</button>
        <button class="btn primary" id="savePrefs" type="button">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    const searchForm = document.getElementById('searchForm');
    searchForm.addEventListener('submit', function (event) {
      event.preventDefault();
      const input = document.getElementById('searchInput');
      const query = input.value.trim();
      if (!query) return;
      const target = '/search?q=' + encodeURIComponent(query);
      window.location.href = target;
    });

    const modal = document.getElementById('prefsModal');
    const openPrefs = document.getElementById('openPrefs');
    const closePrefs = document.getElementById('closePrefs');
    const savePrefs = document.getElementById('savePrefs');

    function openModal() {
      modal.setAttribute('aria-hidden', 'false');
      closePrefs.focus();
    }

    function hideModal() {
      modal.setAttribute('aria-hidden', 'true');
      openPrefs.focus();
    }

    openPrefs.addEventListener('click', openModal);
    closePrefs.addEventListener('click', hideModal);
    savePrefs.addEventListener('click', function () {
      hideModal();
      document.getElementById('cookieBanner').style.display = 'none';
    });

    modal.addEventListener('click', function (event) {
      if (event.target === modal) hideModal();
    });

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') {
        hideModal();
      }
    });

    document.querySelectorAll('.toggle').forEach(function (toggle) {
      toggle.addEventListener('click', function () {
        const checked = toggle.getAttribute('aria-checked') === 'true';
        toggle.setAttribute('aria-checked', checked ? 'false' : 'true');
      });
    });
  </script>
